const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构（示意图）' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '液泡' },
      { kind: 'text', payload: '细胞核' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = Math.min(W, H);

    function rr(x0, y0, x1, y1, r) {
      var w = x1 - x0;
      var h = y1 - y0;
      var rad = Math.max(0, Math.min(r, Math.min(w, h) / 2));
      return [
        ['M', x0 + rad, y0],
        ['L', x1 - rad, y0],
        ['Q', x1, y0, x1, y0 + rad],
        ['L', x1, y1 - rad],
        ['Q', x1, y1, x1 - rad, y1],
        ['L', x0 + rad, y1],
        ['Q', x0, y1, x0, y1 - rad],
        ['L', x0, y0 + rad],
        ['Q', x0, y0, x0 + rad, y0],
        ['Z']
      ];
    }

    function leader(x1, y1, x2, y2) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / len;
      var uy = dy / len;
      var px = -uy;
      var py = ux;
      var hl = Math.max(6, m * 0.018);
      var hw = hl * 0.42;
      var bx = x2 - ux * hl;
      var by = y2 - uy * hl;
      return [
        ['M', x1, y1],
        ['L', bx, by],
        ['M', bx + px * hw, by + py * hw],
        ['L', x2, y2],
        ['L', bx - px * hw, by - py * hw]
      ];
    }

    var paths = [];
    function add(id, cmds) {
      paths.push({ id: id, commands: cmds });
      return id;
    }

    var cx0 = W * 0.10;
    var cy0 = H * 0.16;
    var cx1 = W * 0.64;
    var cy1 = H * 0.86;
    var t = Math.max(6, m * 0.024);

    add('cell-wall', rr(cx0, cy0, cx1, cy1, m * 0.07));
    add('membrane', rr(cx0 + t, cy0 + t, cx1 - t, cy1 - t, Math.max(2, m * 0.07 - t)));

    var ix0 = cx0 + t + 3;
    var iy0 = cy0 + t + 3;
    var ix1 = cx1 - t - 3;
    var iy1 = cy1 - t - 3;
    add('cytoplasm', rr(ix0, iy0, ix1, iy1, Math.max(2, m * 0.07 - t - 3)));

    var iw = ix1 - ix0;
    var ih = iy1 - iy0;

    var vx0 = ix0 + iw * 0.34;
    var vx1 = ix0 + iw * 0.96;
    var vy0 = iy0 + ih * 0.05;
    var vy1 = iy0 + ih * 0.62;
    var vr = Math.min(vx1 - vx0, vy1 - vy0) * 0.42;
    add('vacuole', rr(vx0, vy0, vx1, vy1, vr));
    add('vacuole-inner', rr(vx0 + 4, vy0 + 4, vx1 - 4, vy1 - 4, Math.max(2, vr - 4)));

    var rn = Math.min(iw, ih) * 0.14;
    var nx = ix0 + iw * 0.17;
    var ny = iy0 + ih * 0.78;
    add('nucleus', visualSdk.circle(nx, ny, rn));
    add('nucleus-inner', visualSdk.circle(nx, ny, rn * 0.82));

    var wallPtX = cx0 + (cx1 - cx0) * 0.08;
    var wallPtY = cy0 + t * 0.5;
    add('leader-wall', leader(W * 0.15, H * 0.085, wallPtX, wallPtY));
    add('leader-nucleus', leader(W * 0.165, H * 0.915, nx - rn * 0.20, ny + rn * 0.92));

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'cell-wall', fill: '#8FBF74' },
          { type: 'path', pathId: 'membrane', fill: '#FFFFFF' },
          { type: 'path', pathId: 'cytoplasm', fill: '#EFF8E7' },
          { type: 'path', pathId: 'vacuole', fill: '#9FC9E3' },
          { type: 'path', pathId: 'vacuole-inner', fill: '#D3EBF8' },
          { type: 'path', pathId: 'nucleus', fill: '#8E6BB2' },
          { type: 'path', pathId: 'nucleus-inner', fill: '#BFA5DB' },
          { type: 'path', pathId: 'leader-wall', fill: '#3B4A5A', stroke: { width: 1.6, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'leader-nucleus', fill: '#3B4A5A', stroke: { width: 1.6, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.955 }, hAlign: 'center', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: W * 0.14, y: H * 0.055 }, hAlign: 'center', vAlign: 'middle', color: '#2E5E2E' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: (vx0 + vx1) / 2, y: (vy0 + vy1) / 2 }, hAlign: 'center', vAlign: 'middle', color: '#1F4E6B' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: W * 0.14, y: H * 0.945 }, hAlign: 'center', vAlign: 'middle', color: '#3D2A55' }
        ]
      }
    };
  }
};
